            Assert.DoesNotContain("**Alice Example***Customer Service*", result.Content.ToString());
            Assert.Contains("Alice Example", result.Content.ToString());
            Assert.Contains("Customer Service", result.Content.ToString());
            Assert.Contains("Logo", result.Content.ToString());

